export const BottomDrawer = {
  render: (args, ctx) => new PixiStory({
    context: ctx,
    init: view => {
      const {
        width,
        height,
        radius,
        padding,
        backgroundColor,
        backgroundBorderColor,
        backdropColor,
        backdropAlpha,
        contentColor,
        closeOnBackdropClick,
        swipeToClose
      } = args;
      const drawer = new Drawer({
        background: new Graphics().roundRect(0, 0, width, height, radius).fill(backgroundColor).stroke({
          color: backgroundBorderColor,
          width: 1
        }),
        backdropColor: getColor(backdropColor),
        backdropAlpha,
        content: new Text({
          text: loremText,
          style: {
            ...defaultTextStyle,
            fontSize: 16,
            align: 'center',
            fontWeight: 'normal',
            wordWrapWidth: width - 2 * padding - padding,
            wordWrap: true,
            lineHeight: 20,
            fill: getColor(contentColor)
          }
        }),
        width,
        height,
        padding,
        position: 'bottom',
        closeOnBackdropClick,
        swipeToClose,
        animations: {
          open: {
            props: {},
            duration: 300
          },
          close: {
            props: {},
            duration: 300
          }
        }
      });
      drawer.onClose.connect(() => {
        action('onClose')('Drawer closed');
        setTimeout(() => drawer.open(), 1000);
      });

      // Set screen size for proper positioning
      const canvas = document.getElementById('storybook-root');
      if (canvas) {
        drawer.setScreenSize(canvas.offsetWidth, canvas.offsetHeight);
      }
      view.addChild(drawer);
      drawer.open();
    },
    resize: resizeDrawerStory
  }),
  args: getDefaultArgs(args)
};;
